  "inlineSchema": "// Baza hira_hr (ADR-0096, ADR-0104): sesje przeglądarki i kanał zdarzeń Core (etap 0).\n// Osoba, pracownik i firma pochodzą z MonoriseCore (sub, employee_id i org_id z tokenu), więc HiraHR nie ma własnych kont.\n// Schemat \"auth\": sesje przeglądarki (BFF, @monorise-team/auth). Szukamy ich po skrócie identyfikatora z ciasteczka,\n// zanim wiadomo, czyja to sesja, więc są bez RLS; tokeny w środku są zaszyfrowane.\n// Schemat \"public\": funkcje pomocnicze RLS (migracje) oraz tabele techniczne kanału zdarzeń Core bez danych firmowych.\n// Aplikacja łączy się rolą hira_hr_app bez uprawnień właściciela tabel (ADR-0037); każda tabela domenowa\n// z danymi osób albo firm od etapu 1 dostaje RLS (ENABLE + FORCE) z użyciem funkcji pomocniczych.\n\ngenerator client {\n  provider            = \"prisma-client\"\n  output              = \"../src/generated/prisma\"\n  moduleFormat        = \"esm\"\n  importFileExtension = \"js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  schemas  = [\"public\", \"auth\"]\n}\n\n/// Sesja przeglądarki: tokeny z Core zaszyfrowane po stronie serwera (ADR-0050).\nmodel Session {\n  /// SHA-256 identyfikatora z ciasteczka; samego identyfikatora baza nie zna.\n  id             String   @id\n  /// Konto Monorise (sub z tokenu Core).\n  accountId      String   @map(\"account_id\") @db.Uuid\n  organizationId String   @map(\"organization_id\") @db.Uuid\n  expiresAt      DateTime @map(\"expires_at\") @db.Timestamptz(3)\n  /// Zaszyfrowane tokeny, kontekst firmy i dane osoby.\n  data           String\n  createdAt      DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(3)\n  updatedAt      DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(3)\n\n  @@index([accountId])\n  @@index([expiresAt])\n  @@map(\"sessions\")\n  @@schema(\"auth\")\n}\n\n/// Kursor ostatnio przetworzonego zdarzenia z kanału HTTP produktu (bez danych firmowych, bez RLS).\nmodel EventFeedCursor {\n  /// Nazwa kanału zdarzeń, np. \"core\".\n  id        String   @id\n  /// Numer ostatnio przetworzonego zdarzenia (liczba dziesiętna jako napis).\n  sequence  String\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(3)\n\n  @@map(\"event_feed_cursors\")\n  @@schema(\"public\")\n}\n\n/// Zapis przetworzonych zdarzeń do deduplikacji po stronie odbiorcy (bez danych firmowych, bez RLS).\nmodel ProcessedEvent {\n  consumer    String\n  eventId     String   @map(\"event_id\") @db.Uuid\n  processedAt DateTime @map(\"processed_at\") @db.Timestamptz(3)\n\n  @@id([consumer, eventId])\n  @@index([processedAt])\n  @@map(\"processed_events\")\n  @@schema(\"public\")\n}\n\n// ── Etap 1: kartoteka (ADR-0104) ─────────────────────────────────────────────────────────────────\n// Wszystkie tabele mają wymuszone RLS po organization_id. Pola *_encrypted zawierają wyłącznie szyfrogram\n// AES-256-GCM (format v1.<klucz>.<iv>.<szyfrogram>.<znacznik>), nigdy jawne wartości.\n\nenum ContractType {\n  PROBATION\n  FIXED_TERM\n  INDEFINITE\n  MANDATE\n  SPECIFIC_TASK\n  B2B\n\n  @@schema(\"public\")\n}\n\nenum SensitiveAccessAction {\n  READ\n  UPDATE\n\n  @@schema(\"public\")\n}\n\n/// Stanowisko z katalogu firmy (np. „Magazynierka”). Archiwizowane, nie usuwane, bo wskazują je umowy.\nmodel Position {\n  id             String               @id @db.Uuid\n  organizationId String               @map(\"organization_id\") @db.Uuid\n  name           String\n  description    String?\n  archivedAt     DateTime?            @map(\"archived_at\") @db.Timestamptz(3)\n  createdAt      DateTime             @default(now()) @map(\"created_at\") @db.Timestamptz(3)\n  updatedAt      DateTime             @updatedAt @map(\"updated_at\") @db.Timestamptz(3)\n  contracts      EmploymentContract[]\n\n  @@unique([organizationId, id])\n  @@index([organizationId, archivedAt])\n  @@map(\"positions\")\n  @@schema(\"public\")\n}\n\n/// Kartoteka pracownika Core (`employeeId`): dane kadrowe spoza Core i zaszyfrowane dane wrażliwe.\nmodel EmployeeProfile {\n  organizationId       String    @map(\"organization_id\") @db.Uuid\n  employeeId           String    @map(\"employee_id\") @db.Uuid\n  dateOfBirth          DateTime? @map(\"date_of_birth\") @db.Date\n  personalEmail        String?   @map(\"personal_email\")\n  personalPhone        String?   @map(\"personal_phone\")\n  homeAddress          Json?     @map(\"home_address\") @db.JsonB\n  mailingAddress       Json?     @map(\"mailing_address\") @db.JsonB\n  emergencyContact     Json?     @map(\"emergency_contact\") @db.JsonB\n  peselEncrypted       String?   @map(\"pesel_encrypted\")\n  bankAccountEncrypted String?   @map(\"bank_account_encrypted\")\n  idDocumentEncrypted  String?   @map(\"id_document_encrypted\")\n  createdAt            DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(3)\n  updatedAt            DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(3)\n  updatedByAccountId   String?   @map(\"updated_by_account_id\") @db.Uuid\n\n  @@id([organizationId, employeeId])\n  @@map(\"employee_profiles\")\n  @@schema(\"public\")\n}\n\n/// Umowa pracownika z historią (kolejne wiersze). Wynagrodzenie jest daną wrażliwą (szyfrogram).\nmodel EmploymentContract {\n  id                 String       @id @db.Uuid\n  organizationId     String       @map(\"organization_id\") @db.Uuid\n  employeeId         String       @map(\"employee_id\") @db.Uuid\n  type               ContractType\n  startDate          DateTime     @map(\"start_date\") @db.Date\n  endDate            DateTime?    @map(\"end_date\") @db.Date\n  fteNumerator       Int?         @map(\"fte_numerator\")\n  fteDenominator     Int?         @map(\"fte_denominator\")\n  positionId         String?      @map(\"position_id\") @db.Uuid\n  salaryEncrypted    String?      @map(\"salary_encrypted\")\n  notes              String?\n  createdAt          DateTime     @default(now()) @map(\"created_at\") @db.Timestamptz(3)\n  updatedAt          DateTime     @updatedAt @map(\"updated_at\") @db.Timestamptz(3)\n  createdByAccountId String       @map(\"created_by_account_id\") @db.Uuid\n  position           Position?    @relation(fields: [organizationId, positionId], references: [organizationId, id], onDelete: Restrict)\n\n  @@unique([organizationId, id])\n  @@index([organizationId, employeeId, startDate])\n  @@map(\"employment_contracts\")\n  @@schema(\"public\")\n}\n\n/// Dziennik dostępu do danych wrażliwych: tylko dopisywanie (rola aplikacji ma SELECT i INSERT).\nmodel SensitiveAccessLog {\n  id             String                @id @db.Uuid\n  organizationId String                @map(\"organization_id\") @db.Uuid\n  actorAccountId String                @map(\"actor_account_id\") @db.Uuid\n  employeeId     String                @map(\"employee_id\") @db.Uuid\n  action         SensitiveAccessAction\n  fields         String[]\n  createdAt      DateTime              @default(now()) @map(\"created_at\") @db.Timestamptz(3)\n\n  @@index([organizationId, employeeId, createdAt, id], map: \"sensitive_access_log_org_employee_created_idx\")\n  @@map(\"sensitive_access_log\")\n  @@schema(\"public\")\n}\n",
